-- ============================================================
-- ARTICLE 4: LonWorks (LON) to BACnet Migration Guide
-- Category: Best Practices
-- Sources:
--   ISO/IEC 14908-1:2012 (LonTalk protocol)
--   ANSI/CEA 709.1 (LonTalk standard, 1999)
--   Echelon Corporation / Adesto Technologies / Dialog Semiconductor / Renesas acquisition chain
--   ASHRAE Standard 135-2020 (BACnet)
--   LonMark International (lonmark.org)
-- ============================================================

INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'best-practices'),
  'LonWorks (LON) to BACnet Migration Guide',
  'lonworks-lon-to-bacnet-migration-guide',
  'Planning guide for migrating legacy LonWorks building automation installations to BACnet, covering assessment, gateway strategies, phased cutover, and vendor history.',
  E'# LonWorks (LON) to BACnet Migration Guide\n\nLonWorks (Local Operating Network) installations are found in thousands of buildings worldwide, but the protocol''s market trajectory has shifted. Echelon Corporation, the original developer, was acquired by Adesto Technologies in 2018, which was then acquired by Dialog Semiconductor in 2020, which was subsequently acquired by Renesas Electronics. As chip supply and vendor support narrow, many building owners are migrating LON systems to BACnet.\n\nSource: Wilson Sonsini, "Echelon to Be Acquired by Adesto" (2018); Dialog Semiconductor press release, "Completion of Adesto Acquisition" (June 2020).\n\n## LonWorks Overview\n\n| Attribute | Detail |\n|---|---|---|\n| Standard | ISO/IEC 14908, ANSI/CEA 709.1 |\n| Protocol | LonTalk |\n| Physical Layer | FT-10 free topology twisted pair (78 kbps) |\n| Processor | Neuron Chip (3x 8-bit processors) |\n| Programming | Neuron C |\n| Addressing | 48-bit Neuron ID, domain/subnet/node |\n| Interoperability | LonMark-certified Standard Network Variable Types (SNVTs) |\n| Installed base | ~90 million devices as of 2010 |\n\nSource: ISO/IEC 14908-1:2012; LonMark International (lonmark.org); Wikipedia, "LonWorks."\n\n## When to Migrate\n\n| Trigger | Description |\n|---|---|---|\n| End-of-life hardware | Neuron Chips or LonWorks controllers no longer available from original manufacturer |\n| Vendor support declining | Fewer technicians trained on LON; shrinking parts supply |\n| IT convergence | Enterprise IT requiring IP-based protocols for network management |\n| Cloud connectivity | LON has no native cloud/IP pathway without gateways |\n| Cybersecurity requirements | LON lacks built-in encryption and authentication |\n| System expansion | New equipment ships with BACnet, not LON |\n\n## Migration Strategies\n\n### Strategy 1: Gateway Approach\n\nInstall LON-to-BACnet gateways to expose existing LON devices as BACnet objects on the IP network:\n\n```\nExisting LON Devices ←→ LON-to-BACnet Gateway ←→ BACnet/IP Network\n   (FT-10 bus)           (protocol translator)       (Ethernet)\n```\n\n| Advantage | Disadvantage |\n|---|---|\n| Preserves existing field wiring and controllers | Adds latency and a potential point of failure |\n| Lowest upfront cost | LON hardware still ages and eventually fails |\n| Fastest deployment | Gateway capacity limits may require multiple units |\n| No reprogramming of existing controllers | Two protocols to maintain |\n\nGateway vendors include Loytec, Contemporary Controls, and Chipkin, among others.\n\nSource: Chipkin, "LonWorks to BACnet IP QuickServer Gateway" (store.chipkin.com); Contemporary Controls product documentation.\n\n### Strategy 2: Rip-and-Replace\n\nReplace LON controllers with native BACnet controllers:\n\n```\nNew BACnet Controllers ←→ BACnet/IP Network\n  (replace LON devices)       (Ethernet)\n```\n\n| Advantage | Disadvantage |\n|---|---|\n| Clean, modern infrastructure | Highest upfront cost |\n| Full BACnet feature set | Requires reprogramming all control sequences |\n| No legacy protocol to maintain | Extended project timeline |\n| Better long-term support | May require new field wiring |\n\n### Strategy 3: Phased Hybrid\n\nCombine gateways for immediate integration with gradual controller replacement:\n\n```\nPhase 1: Install gateways for LON-to-BACnet bridging\nPhase 2: Replace LON controllers floor-by-floor or system-by-system\nPhase 3: Remove gateways as LON devices are decommissioned\n```\n\nThis is the most common approach for occupied buildings where a full cutover is not practical.\n\n## Assessment Checklist\n\nBefore starting migration, document the existing LON installation:\n\n```\nSite Assessment:\n  [ ] Inventory all LON devices (type, Neuron ID, location)\n  [ ] Document FT-10 trunk topology and wiring paths\n  [ ] Identify LonMark SNVT types in use\n  [ ] Record all control sequences and interlocks\n  [ ] Note which devices are approaching end of life\n  [ ] Identify devices that cannot be replaced (embedded in equipment)\n  [ ] Map LON network variables to equivalent BACnet objects\n  [ ] Assess available Ethernet infrastructure for BACnet/IP\n  [ ] Determine budget and timeline constraints\n```\n\n## LON-to-BACnet Object Mapping\n\nCommon LON SNVT types and their BACnet equivalents:\n\n| LON SNVT | LON Type | BACnet Object | BACnet Type |\n|---|---|---|---|\n| SNVT_temp_p | Temperature (°C, 0.01 res) | Analog Input | degrees-celsius |\n| SNVT_lev_percent | Percentage (0–100%) | Analog Value | percent |\n| SNVT_switch | On/Off + level | Binary Value or Analog Value | — |\n| SNVT_hvac_mode | HVAC mode enum | Multi-state Value | — |\n| SNVT_occupancy | Occupied/Unoccupied | Binary Value | — |\n| SNVT_flow | Flow rate | Analog Input | Engineering units vary |\n\nSource: LonMark International SNVT Master List; ASHRAE Standard 135-2020 object types.\n\n## Phased Cutover Plan\n\n| Phase | Duration | Activities |\n|---|---|---|\n| 1. Assessment | 2–4 weeks | Site survey, device inventory, sequence documentation |\n| 2. Design | 2–4 weeks | Gateway placement, BACnet addressing plan, object mapping |\n| 3. Gateway install | 1–2 weeks | Install and configure LON-to-BACnet gateways |\n| 4. Parallel operation | 4–8 weeks | Run both protocols, verify BACnet points match LON values |\n| 5. Controller replacement | Ongoing | Replace LON controllers as budget allows |\n| 6. Decommission | As completed | Remove gateways and LON wiring when no longer needed |\n\n## Common Pitfalls\n\n| Pitfall | Prevention |\n|---|---|\n| Incomplete device inventory | Walk every floor; do not rely solely on drawings |\n| Missing sequence documentation | Capture running sequences before disconnecting anything |\n| Gateway capacity exceeded | Verify gateway point limits before purchase |\n| SNVT-to-BACnet type mismatch | Test object mapping on a sample before full deployment |\n| Network disruption during cutover | Schedule work during low-occupancy periods |\n\n## References\n\n- ISO/IEC 14908-1:2012: Control Network Protocol (LonTalk)\n- ANSI/CEA 709.1: Control Network Protocol Specification\n- ASHRAE Standard 135-2020: BACnet\n- LonMark International (lonmark.org)\n- Chipkin, "LonWorks to BACnet IP QuickServer Gateway" (store.chipkin.com)\n- Wilson Sonsini, "Echelon to Be Acquired by Adesto" (wsgr.com, 2018)\n- Dialog Semiconductor, "Completion of Adesto Acquisition" (design-reuse.com, 2020)',
  true
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO wiki_article_facets (article_id, facet_id)
SELECT a.id, f.id
FROM wiki_articles a
CROSS JOIN wiki_facets f
WHERE a.slug = 'lonworks-lon-to-bacnet-migration-guide'
  AND f.slug IN ('lon', 'bacnet', 'networking', 'integration', 'commissioning')
ON CONFLICT DO NOTHING;

-- ============================================================
-- ARTICLE 5: Energy Monitoring and Measurement & Verification in BAS
-- Category: Best Practices
-- Sources:
--   Efficiency Valuation Organization (EVO), "IPMVP Core Concepts 2022"
--   ASHRAE Guideline 14-2023: Measurement of Energy, Demand, and Water Savings
--   U.S. DOE, "M&V Guidelines: Measurement and Verification for Performance-Based Contracts, Version 4.0"
--   ASHRAE Standard 135-2020 (Accumulator and Pulse Converter objects)
--   USGBC, LEED v4.1 EAc Advanced Energy Metering
--   U.S. EPA, ENERGY STAR Portfolio Manager
-- ============================================================

INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'best-practices'),
  'Energy Monitoring and Measurement & Verification in BAS',
  'energy-monitoring-measurement-verification-bas',
  'Best-practice guide to BAS energy monitoring, submetering, IPMVP M&V options, ASHRAE Guideline 14, and reporting requirements for ENERGY STAR and LEED.',
  E'# Energy Monitoring and Measurement & Verification in BAS\n\nBuilding automation systems are increasingly expected to do more than control HVAC — they must demonstrate energy performance. Measurement and Verification (M&V) provides the framework for quantifying energy savings from efficiency projects, and the BAS is often the primary data source.\n\n## Common Energy Metering Points\n\n| Meter Type | Measures | Typical Location | BAS Integration |\n|---|---|---|---|\n| Electrical submeter | kWh, kW demand, voltage, current, power factor | Electrical panels (floors, tenants, mechanical) | Modbus RTU/TCP or BACnet |\n| BTU meter | Thermal energy (BTU or ton-hours) | Chilled water, hot water, condenser water piping | Modbus or BACnet; combines flow + delta-T |\n| Gas meter | Cubic feet or therms | Boiler feeds, kitchen, lab supply | Pulse output to BAS controller |\n| Water meter | Gallons or liters | Domestic main, cooling tower makeup, irrigation | Pulse output or Modbus |\n| Steam meter | Pounds per hour or klbs | District steam risers | Modbus or 4–20 mA |\n\nSource: GSA, "Submetering Business Case"; Intellimeter, "Integrating Submetering to BAS."\n\n## BACnet Objects for Energy Monitoring\n\nASHRAE Standard 135 defines two object types specifically for metering:\n\n### Accumulator (Object Type 23)\n\nRepresents a device that measures quantities by counting pulses (e.g., kWh meter with pulse output):\n\n| Property | Description |\n|---|---|\n| Present_Value | Accumulated pulse count since last reset |\n| Pulse_Rate | Pulses received during the most recent period |\n| Prescale | Multiplier and modulo-divide for converting raw pulses to engineering units |\n| Max_Pres_Value | Rollover threshold |\n\n### Pulse Converter (Object Type 24)\n\nConverts raw pulse counts from an Accumulator into scaled engineering values:\n\n| Property | Description |\n|---|---|\n| Scale_Factor | Multiplier applied to Count |\n| Count | Raw accumulated pulse count |\n| Present_Value | Count × Scale_Factor (e.g., kWh, gallons) |\n\nSource: ASHRAE Standard 135-2020, Clauses 12.1 and 12.25; Chipkin, "BACnet Pulse Converter Object."\n\n## IPMVP Framework\n\nThe International Performance Measurement and Verification Protocol (IPMVP), maintained by the Efficiency Valuation Organization (EVO), defines four M&V approaches:\n\n| Option | Name | Method | Best For |\n|---|---|---|---|\n| A | Retrofit Isolation: Key Parameter Measurement | Measure key parameters; stipulate others from historical data | Simple retrofits with well-understood savings (e.g., lighting upgrade) |\n| B | Retrofit Isolation: All Parameter Measurement | Measure all energy parameters directly; no stipulation | System-level optimizations (e.g., chiller plant, AHU) |\n| C | Whole Facility | Analyze whole-building utility meter data with regression analysis | Large-scale retrofits where savings exceed ~10% of total consumption |\n| D | Calibrated Simulation | Use a calibrated energy model to determine savings | No baseline metered data available, or complex bundled measures |\n\nOptions A and B isolate individual measures; Options C and D assess savings at the whole-facility level.\n\nSource: Efficiency Valuation Organization, "IPMVP Core Concepts 2022" (evo-world.org).\n\n## ASHRAE Guideline 14\n\nASHRAE Guideline 14-2023 (Measurement of Energy, Demand, and Water Savings) provides detailed procedures for implementing M&V. It defines calibration thresholds for energy models:\n\n| Metric | Monthly Threshold | Hourly Threshold |\n|---|---|---|\n| NMBE (Normalized Mean Bias Error) | ±5% | ±10% |\n| CV(RMSE) (Coefficient of Variation of RMSE) | ≤15% | ≤30% |\n\nA simulation model is considered calibrated when it meets both thresholds simultaneously at the given time interval.\n\nSource: ASHRAE Guideline 14-2023; ORNL, "Suitability of ASHRAE Guideline 14 Metrics."\n\n## ENERGY STAR Portfolio Manager\n\nENERGY STAR Portfolio Manager requires:\n\n- Property information (address, gross floor area, property type, year built)\n- Use details (occupancy, operating hours, number of workers)\n- All fuel type meters covering whole-building consumption\n- Minimum 12 full consecutive calendar months of meter data\n\nBAS trend data and submeters can feed Portfolio Manager through its Web Services API for automated data exchange.\n\nSource: U.S. EPA, ENERGY STAR Portfolio Manager (energystar.gov/buildings/benchmark).\n\n## LEED Energy Metering Requirements\n\nLEED v4.1 defines two metering levels:\n\n### EAp Building-Level Energy Metering (Prerequisite)\n\n- Whole-building energy meters for all sources\n- Data shared with USGBC for 5 years post-certification at monthly minimum intervals\n\n### EAc Advanced Energy Metering (Credit)\n\n- Permanently installed meters recording at 1-hour or shorter intervals\n- Data transmitted to a remote location\n- Any individual end use representing 10% or more of total annual consumption must be independently metered\n- Must report hourly, daily, monthly, and annual consumption\n\nSource: USGBC, LEED v4.1 BD+C Energy and Atmosphere credits (usgbc.org).\n\n## BAS Data Strategy for M&V\n\n### What to Trend\n\n| Data Point | Interval | Purpose |\n|---|---|---|\n| Whole-building electric (kWh) | 15 minutes | IPMVP Option C baseline |\n| Chilled water BTU | 15 minutes | Plant efficiency tracking |\n| Hot water BTU | 15 minutes | Heating energy tracking |\n| Natural gas (therms) | 15 minutes or hourly | Boiler efficiency |\n| Outdoor air temperature | 15 minutes | Weather normalization |\n| Building occupancy | 15 minutes or schedule | Occupancy adjustment |\n| Individual AHU energy | 15 minutes | IPMVP Option B isolation |\n| Lighting circuit kWh | 15 minutes | IPMVP Option A verification |\n\n### Data Quality Checks\n\nBefore using BAS data for M&V, validate:\n\n```\nData Quality Checklist:\n  [ ] No gaps exceeding 1 hour in critical meters\n  [ ] Values within physically plausible range\n  [ ] Timestamps synchronized across all meters (NTP)\n  [ ] Meter calibration current (annual for revenue meters)\n  [ ] Pulse count rollover handled correctly\n  [ ] Units consistent across all data sources\n  [ ] Minimum 12 months of baseline data collected\n```\n\n## References\n\n- Efficiency Valuation Organization, "IPMVP Core Concepts 2022" (evo-world.org)\n- ASHRAE Guideline 14-2023: Measurement of Energy, Demand, and Water Savings\n- U.S. DOE, "M&V Guidelines Version 4.0" (energy.gov)\n- ASHRAE Standard 135-2020: BACnet (Accumulator and Pulse Converter object types)\n- U.S. EPA, ENERGY STAR Portfolio Manager (energystar.gov)\n- USGBC, LEED v4.1 BD+C Advanced Energy Metering (usgbc.org)\n- GSA, Submetering Business Case (gsa.gov)',
  true
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO wiki_article_facets (article_id, facet_id)
SELECT a.id, f.id
FROM wiki_articles a
CROSS JOIN wiki_facets f
WHERE a.slug = 'energy-monitoring-measurement-verification-bas'
  AND f.slug IN ('energy-management', 'analytics', 'bacnet', 'commissioning')
ON CONFLICT DO NOTHING;

-- ============================================================
-- Update facet article_count from actual data
-- ============================================================

UPDATE wiki_facets f
SET article_count = COALESCE(counts.cnt, 0)
FROM (
  SELECT facet_id, COUNT(*) as cnt
  FROM wiki_article_facets
  GROUP BY facet_id
) counts
WHERE f.id = counts.facet_id;

UPDATE wiki_facets SET article_count = 0
WHERE id NOT IN (SELECT DISTINCT facet_id FROM wiki_article_facets);
